\title{An Improved Vizing-Type Constant for Domination\\ in Cartesian Products of Graphs}
\author{Aristotle}
\date{2026-07-02}

\begin{document}
\maketitle

\begin{abstract}
Vizing's conjecture asserts that the domination number of the Cartesian product of
two finite graphs is at least the product of their domination numbers,
$\gam(G \bx H) \ge \gam(G)\,\gam(H)$; it remains open after more than half a century.
The best known unconditional multiplicative bounds have the form
$\gam(G \bx H) \ge c\,\gam(G)\,\gam(H)$, beginning with the Clark--Suen constant
$c = \tfrac12$ and improved in subsequent work to a constant of the form
$\tfrac{19-\sqrt{73}}{18} \approx 0.5809$. This paper isolates and rigorously
establishes the arithmetic of that improved constant and proves the associated
Vizing-type inequality in every case forced by the elementary projection bound. We
prove that $c = \tfrac{19-\sqrt{73}}{18}$ is precisely the smaller root of the
integer quadratic $9x^2 - 19x + 8$, that it lies strictly between the Clark--Suen
constant $\tfrac12$ and the conjectural Vizing constant $1$, and that it is positive.
We frame these facts inside the two-sided bracket
$\max(\gam(G),\gam(H)) \le \gam(G\bx H) \le \gam(G)\,|V(H)|$, whose lower half is a
coordinate-projection argument, and we deduce that whenever
$\min(\gam(G),\gam(H)) \le 1$ the inequality $\gam(G\bx H) \ge c\,\gam(G)\,\gam(H)$
holds. We discuss the discharging obstruction to the unconditional bound, sharpness
of the lower bracket, and the fractional relaxation.
\end{abstract}

\section{Introduction}

\subsection{Domination}
Let $G = (V, E)$ be a finite simple graph. A set $S \subseteq V$ is a
\emph{dominating set} if every vertex not in $S$ is adjacent to a vertex of $S$;
equivalently, every $v$ satisfies $v \in S$ or has a neighbour in $S$. The
\emph{domination number} $\gam(G)$ is the minimum size of a dominating set.
Domination models the placement of a minimum number of guards, sensors, or
facilities so that every location is watched or served.

\subsection{The Cartesian product}
Given graphs $G$ on vertex set $A$ and $H$ on vertex set $B$, their
\emph{Cartesian (box) product} $G \bx H$ has vertex set $A \times B$, and
$(a_1,b_1)$ is adjacent to $(a_2,b_2)$ iff either $a_1 = a_2$ and $b_1 \sim b_2$ in
$H$, or $b_1 = b_2$ and $a_1 \sim a_2$ in $G$. The defining
\emph{fixed-coordinate property} is that every product edge leaves one coordinate
unchanged. Cartesian products model grids, tori, and hypercubes.

\subsection{Vizing's conjecture and multiplicative bounds}
Vizing (1968) conjectured $\gam(G\bx H) \ge \gam(G)\,\gam(H)$, still open. The
principal unconditional progress is a bound $\gam(G\bx H) \ge c\,\gam(G)\,\gam(H)$
with explicit constant $c$: Clark and Suen (2000) proved $c = \tfrac12$, and
refinements of their partition-and-charge argument raise the constant to
\[ c \;=\; \frac{19 - \sqrt{73}}{18} \;\approx\; 0.5809. \]

\subsection{Contributions}
We (1) pin down $c$ as the smaller root of $9x^2 - 19x + 8$ and prove
$\tfrac12 < c < 1$; (2) establish the two-sided bracket via cylindrification and
projection; and (3) prove the Vizing-type inequality with constant $c$ whenever
$\min(\gam(G),\gam(H)) \le 1$. We claim no more: the unconditional constant is deep
and not asserted here.

\section{Definitions}

\begin{definition}[Dominating set]
For $G$ on $V$ and $S \subseteq V$, $S$ is \emph{dominating} if for every $v \in V$
either $v \in S$ or some $w \in S$ is adjacent to $v$.
\end{definition}

\begin{definition}[Domination number]
$\gam(G) = \min\{\,|S| : S \text{ is a dominating set of } G\,\}$, attained for a
nonempty finite graph.
\end{definition}

\begin{definition}[The improved constant]
$c := \dfrac{19 - \sqrt{73}}{18}.$
\end{definition}

\section{The arithmetic of the constant}

\begin{theorem}[Quadratic identity]\label{thm:root}
$c = \tfrac{19-\sqrt{73}}{18}$ satisfies $9c^2 - 19c + 8 = 0$, and is the smaller of
the two roots $\tfrac{19 \pm \sqrt{73}}{18}$ of $9x^2 - 19x + 8$.
\end{theorem}
\begin{proof}
Write $s = \sqrt{73}$, so $s^2 = 73$. Then
$9c^2 = \tfrac{(19-s)^2}{36} = \tfrac{361 - 38s + 73}{36} = \tfrac{434 - 38s}{36}$
and $19c = \tfrac{361 - 19s}{18} = \tfrac{722 - 38s}{36}$, hence
\[ 9c^2 - 19c + 8 = \frac{(434 - 38s) - (722 - 38s) + 288}{36} = \frac{0}{36} = 0. \]
The roots of $9x^2 - 19x + 8$ are $\tfrac{19 \pm \sqrt{361 - 288}}{18} =
\tfrac{19 \pm \sqrt{73}}{18}$, and $c$ takes the minus sign.
\end{proof}

\begin{theorem}[Strict improvement over Clark--Suen]\label{thm:half}
$\tfrac12 < c$.
\end{theorem}
\begin{proof}
Since $73 < 100$ and $\sqrt{\cdot}$ is increasing, $\sqrt{73} < 10$, so
$19 - \sqrt{73} > 9$ and $c > \tfrac{9}{18} = \tfrac12$.
\end{proof}

\begin{theorem}[Below the Vizing constant]\label{thm:one}
$c < 1$.
\end{theorem}
\begin{proof}
Since $1 < 73$, $\sqrt{73} > 1$, so $19 - \sqrt{73} < 18$ and $c < 1$.
\end{proof}

\begin{corollary}[Location]
$0 < \tfrac12 < c < 1$, and numerically $c = 0.58091\ldots$
\end{corollary}

\section{The two-sided bracket for product domination}
Let $G$ be on vertex set $A$ and $H$ on vertex set $B$.

\begin{theorem}[Cylindrification upper bound]\label{thm:upper}
$\gam(G \bx H) \le \gam(G)\cdot |B|.$
\end{theorem}
\begin{proof}
Let $D \subseteq A$ be a minimum dominating set of $G$. Set $S = D \times B$, of
size $\gam(G)\,|B|$. For any $(a',b')$: since $D$ dominates $G$, either $a' \in D$
(so $(a',b') \in S$) or some $a \in D$ is adjacent to $a'$ in $G$, whence
$(a,b') \in S$ is adjacent to $(a',b')$ (same second coordinate). Thus $S$ dominates
$G\bx H$.
\end{proof}

\begin{theorem}[Projection lower bound]\label{thm:lower}
If $B \ne \varnothing$ then $\gam(G) \le \gam(G\bx H)$; symmetrically, if
$A \ne \varnothing$ then $\gam(H) \le \gam(G\bx H)$. Hence for nonempty $A,B$,
$\max(\gam(G),\gam(H)) \le \gam(G\bx H)$.
\end{theorem}
\begin{proof}
Let $T$ be a minimum dominating set of $G\bx H$ and $\pi_A(T)$ its first-coordinate
projection, so $|\pi_A(T)| \le |T|$. Fix $a' \in A$; pick $b' \in B$ (using
$B \ne \varnothing$). As $T$ dominates the product, either $(a',b') \in T$ (so
$a' \in \pi_A(T)$) or some $(a,b) \in T$ is adjacent to $(a',b')$. By the
fixed-coordinate property, either $b = b'$ and $a \sim a'$ in $G$ (so
$a \in \pi_A(T)$ dominates $a'$), or $a = a'$ (so $a' \in \pi_A(T)$). Thus
$\pi_A(T)$ dominates $G$ and $\gam(G) \le |T| = \gam(G\bx H)$. The other statement is
symmetric.
\end{proof}

\begin{remark}
The nonemptiness hypotheses are essential: without a fibre to test against, the
projection is vacuous and the inequality can fail for the empty graph.
\end{remark}

\begin{corollary}[Bracket]
For nonempty $A,B$,
$\max(\gam(G),\gam(H)) \le \gam(G\bx H) \le \gam(G)\,|V(H)|.$
\end{corollary}

\begin{remark}
For $G=H=K_2$, $\gam=1$ and $K_2 \bx K_2 = C_4$ has $\gam = 2$; indeed
$1 \le 2 \le 2$. For $P_3$ ($\gam=1$) and $K_2$ ($\gam=1$), the $2\times 3$ grid has
$\gam = 2 \in [1,2]$.
\end{remark}

\section{The conditional Vizing-type inequality}

\begin{theorem}[Conditional improved Vizing bound]\label{thm:cond}
Let $G,H$ be finite graphs on nonempty vertex sets and $c = \tfrac{19-\sqrt{73}}{18}$.
If $\min(\gam(G),\gam(H)) \le 1$, then $\gam(G\bx H) \ge c\,\gam(G)\,\gam(H)$.
\end{theorem}
\begin{proof}
Write $a = \gam(G)$, $b = \gam(H)$, $D = \gam(G\bx H)$. By
Theorem~\ref{thm:lower}, $a \le D$ and $b \le D$; by
Theorems~\ref{thm:half}--\ref{thm:one}, $0 < c < 1$. Assume WLOG $a \le b$, so
$a = \min(a,b) \le 1$. Then
\[ c\,a\,b \le c\,b \le b \le D, \]
using $a \le 1$ (with $c,b\ge 0$), then $c < 1$ (with $b \ge 0$), then the
projection bound. Hence $D \ge c\,\gam(G)\,\gam(H)$.
\end{proof}

\section{Discussion}
The value $\tfrac{19-\sqrt{73}}{18}$ is where two competing spending rates in the
partition-and-charge method cross, encoded by $9x^2 - 19x + 8$. The projection
argument pays only for the fixed-coordinate half of each product edge; recovering the
moving-coordinate half via discharging reproduces the quadratic. Our conditional
theorem makes explicit that the elementary machinery already delivers $c$ whenever one
factor has domination number at most one, and localizes the remaining difficulty to
the discharging step for the $\min(\gam) \ge 2$ regime.

\section{Future directions}
\begin{itemize}
\item \textbf{Unconditional constant.} Conjecturally $\gam(G\bx H) \ge
\tfrac{19-\sqrt{73}}{18}\,\gam(G)\,\gam(H)$ for all $G,H$, with the constant best
possible for partition-and-charge; the remaining ingredient is the charging
inequality for the $\min \ge 2$ regime.
\item \textbf{Sharpness of the lower bracket.} For every $k$, seek $G,H$ with
$\gam(G)=\gam(H)=k$ and $\gam(G\bx H)=k$; a universal fibre collapses the product's
domination number to one factor.
\item \textbf{Fractional relaxation.} Conjecturally $\gam_f(G\bx H) =
\gam_f(G)\,\gam_f(H)$ exactly, with the integrality gap forcing the deficit
$\tfrac{19-\sqrt{73}}{18}$ in the integral case.
\item \textbf{Upper-bracket refinement.} Replace $\gam(G)\,|V(H)|$ by covering
arguments over only the fibres needed to dominate.
\end{itemize}

\section{Conclusion}
We gave a self-contained account of $c = \tfrac{19-\sqrt{73}}{18}$: the smaller root
of $9x^2 - 19x + 8$, strictly between $\tfrac12$ and $1$, positive. Inside the
bracket $\max(\gam(G),\gam(H)) \le \gam(G\bx H) \le \gam(G)\,|V(H)|$, it yields
$\gam(G\bx H) \ge c\,\gam(G)\,\gam(H)$ whenever one factor has domination number at
most one, delimiting the reach of the projection method.

\end{document}

