"""
Demo 3: Projection lower bound certificate.

Given an optimal dominating set T of a Cartesian product G [] H, its projection
onto the first coordinate is a dominating set of G. This demo constructs T,
projects it, and verifies both that the projection dominates G and that
|projection| <= |T|, thereby certifying gamma(G) <= gamma(G [] H).
"""

from __future__ import annotations

from itertools import combinations
from typing import List, Set, Tuple


def path_adj(n: int) -> List[Set[int]]:
    """Adjacency (open neighbourhoods) of the path P_n."""
    adj: List[Set[int]] = [set() for _ in range(n)]
    for i in range(n - 1):
        adj[i].add(i + 1)
        adj[i + 1].add(i)
    return adj


def dominates(adj: List[Set[int]], s: Set[int]) -> bool:
    """Does s dominate the graph with adjacency adj?"""
    for v in range(len(adj)):
        if v not in s and not (adj[v] & s):
            return False
    return True


def min_dominating_set(adj: List[Set[int]]) -> Set[int]:
    """Smallest dominating set by increasing-size search."""
    n = len(adj)
    for k in range(n + 1):
        for sub in combinations(range(n), k):
            s = set(sub)
            if dominates(adj, s):
                return s
    return set(range(n))


def box_adj(ag: List[Set[int]], ah: List[Set[int]]) -> Tuple[List[Set[int]], int]:
    """Adjacency of G [] H, vertices indexed a*nh + b; returns (adj, nh)."""
    ng, nh = len(ag), len(ah)
    adj: List[Set[int]] = [set() for _ in range(ng * nh)]

    def idx(a: int, b: int) -> int:
        return a * nh + b

    for a in range(ng):
        for b in range(nh):
            for b2 in ah[b]:
                adj[idx(a, b)].add(idx(a, b2))
            for a2 in ag[a]:
                adj[idx(a, b)].add(idx(a2, b))
    return adj, nh


def main() -> None:
    g = path_adj(4)   # P4, gamma = 2
    h = path_adj(3)   # P3, gamma = 1
    prod, nh = box_adj(g, h)
    t = min_dominating_set(prod)
    proj = {v // nh for v in t}
    print(f"gamma(G) = {len(min_dominating_set(g))}")
    print(f"optimal T in G[]H: {sorted(t)}  (size {len(t)} = gamma(G[]H))")
    print(f"projection to first coord: {sorted(proj)} (size {len(proj)})")
    print(f"projection dominates G? {dominates(g, proj)}")
    print(f"|proj| <= |T|? {len(proj) <= len(t)}  "
          f"=> gamma(G) <= gamma(G[]H): {len(proj) <= len(t)}")


if __name__ == "__main__":
    main()

